    this.bookingService.clearCurrentBooking();
  }
  // ================================
  // 📋 INICIALIZACIÓN
  // ================================
  loadPropertyAndInitializeBooking() {
    const propertyId = this.route.snapshot.paramMap.get('id');
    if (!propertyId) {
      this.error = 'ID de propiedad no válido';
      this.isLoading = false;
      return;
    }
    combineLatest([this.propertyService.getPropertyById(propertyId), this.bookingService.initializeBooking(propertyId)]).pipe(takeUntil(this.destroy$), catchError(error => {
      this.error = 'Error al cargar la propiedad: ' + error.message;
      this.isLoading = false;
      return of([null, null]);
    })).subscribe(([property, booking]) => {
      if (property && booking) {
        this.property = property;
        this.currentBooking = booking;
        this.initializeCalendar();
        this.isLoading = false;
        // Mostrar información inicial
