    this.detailsForm = this.fb.group({
      firstName: ['', [Validators.required, Validators.minLength(2)]],
      lastName: ['', [Validators.required, Validators.minLength(2)]],
      email: ['', [Validators.required, Validators.email]],
      phone: ['', [Validators.required, Validators.pattern(/^\+?[\d\s\-\(\)]{8,15}$/)]],
      whatsapp: [''],
      documentType: ['cedula', Validators.required],
      documentNumber: ['', [Validators.required, Validators.minLength(6)]],
      nationality: ['Colombiana', Validators.required],
      specialRequests: [''],
      estimatedArrivalTime: [''],
      purposeOfStay: ['vacation', Validators.required],
      isFirstTimeInArmenia: [true],
      emergencyContactName: [''],
      emergencyContactPhone: [''],
      emergencyContactRelationship: ['']
    });
  }
  setupFormSubscriptions() {
    // Escuchar cambios en fechas
    this.datesForm.valueChanges.pipe(takeUntil(this.destroy$)).subscribe(dates => {
      if (dates.checkInDate && dates.checkOutDate) {
        this.updateBookingDates(dates.checkInDate, dates.checkOutDate);
      }
    });
    // Escuchar cambios en huéspedes
    this.guestsForm.valueChanges.pipe(takeUntil(this.destroy$)).subscribe(guests => {
      const totalGuests = guests.adults + guests.children + guests.infants;
      this.updateBookingGuests({
        adults: guests.adults,
        children: guests.children,
        infants: guests.infants,
        total: totalGuests
      });
    });
    // Escuchar cambios en detalles
    this.detailsForm.valueChanges.pipe(takeUntil(this.destroy$)).subscribe(details => {
      this.updateBookingDetails(details);
    });
  }
  setupBookingSubscriptions() {
    // Escuchar progreso del booking
    this.bookingService.bookingProgress$.pipe(takeUntil(this.destroy$)).subscribe(progress => {
      if (progress) {
        this.bookingProgress = progress;
        this.currentStep = progress.currentStep;
        this.canProceed = progress.canProceed;
      }
    });
    // Escuchar booking actual
    this.bookingService.currentBooking$.pipe(takeUntil(this.destroy$)).subscribe(booking => {
      if (booking) {
        this.currentBooking = booking;
        this.updateFormsFromBooking(booking);
      }
    });
  }
  // ================================
  // 📅 GESTIÓN DE CALENDARIO
  // ================================
  initializeCalendar() {
    const today = new Date();
    this.loadCalendarMonth(today.getFullYear(), today.getMonth());
  }
  loadCalendarMonth(year, month) {
    if (!this.property) return;
    this.bookingService.getCalendarMonth(this.property.id, year, month).pipe(takeUntil(this.destroy$)).subscribe(calendarMonth => {
      this.currentMonth = calendarMonth;
    });
  }
  toggleCalendar(mode) {
    this.calendarMode = mode;
    this.showCalendar = !this.showCalendar;
    console.log('Calendar toggled:', {
      mode,
      show: this.showCalendar
    });
    // Si no tenemos datos del calendario, cargar
    if (this.showCalendar && !this.currentMonth) {
      this.initializeCalendar();
    }
  }
  onDateSelect(date) {
    console.log('Date selected:', {
      date,
      mode: this.calendarMode
    });
    if (this.calendarMode === 'check-in') {
      this.selectedDates.checkIn = date;
      this.datesForm.patchValue({
        checkInDate: date
      });
      console.log('Check-in set:', date);
      // Si ya hay check-out, validar
      if (this.selectedDates.checkOut) {
        this.validateSelectedDates();
      } else {
        // Cambiar a modo check-out
        this.calendarMode = 'check-out';
        console.log('Switched to check-out mode');
      }
    } else {
      this.selectedDates.checkOut = date;
      this.datesForm.patchValue({
        checkOutDate: date
      });
      console.log('Check-out set:', date);
      this.validateSelectedDates();
      this.showCalendar = false;
    }
    // Actualizar el booking
    this.updateBookingDates(this.selectedDates.checkIn || '', this.selectedDates.checkOut || '');
  }
  validateSelectedDates() {
    if (!this.property || !this.selectedDates.checkIn || !this.selectedDates.checkOut) {
      console.log('Cannot validate: missing data', {
        property: !!this.property,
        checkIn: this.selectedDates.checkIn,
        checkOut: this.selectedDates.checkOut
      });
      return;
    }
    console.log('Validating dates:', {
      checkIn: this.selectedDates.checkIn,
      checkOut: this.selectedDates.checkOut,
      propertyId: this.property.id
    });
    this.bookingService.validateDateSelection(this.property.id, this.selectedDates.checkIn, this.selectedDates.checkOut).pipe(takeUntil(this.destroy$)).subscribe({
      next: validation => {
        console.log('Date validation result:', validation);
        this.dateValidation = validation;
        this.selectedDates.isValid = validation.isValid;
        this.selectedDates.errors = validation.errors.map(e => e.message);
        this.selectedDates.warnings = validation.warnings.map(w => w.message);
        if (validation.isValid) {
          this.calculatePrice();
        }
      },
      error: error => {
        console.error('Date validation error:', error);
        // Continúa con cálculo básico aunque falle la validación
        this.calculatePrice();
      }
    });
  }
  // ================================
  // 💰 CÁLCULO DE PRECIOS
  // ================================
  calculatePrice() {
    if (!this.property || !this.selectedDates.checkIn || !this.selectedDates.checkOut) {
      console.log('Cannot calculate price: missing data');
      return;
    }
    console.log('Calculating price for:', {
      propertyId: this.property.id,
      checkIn: this.selectedDates.checkIn,
      checkOut: this.selectedDates.checkOut,
      basePrice: this.property.pricePerNight
    });
    this.bookingService.calculatePrice(this.property.id, this.selectedDates.checkIn, this.selectedDates.checkOut).pipe(takeUntil(this.destroy$)).subscribe({
      next: priceBreakdown => {
        console.log('Price calculation result:', priceBreakdown);
        this.priceBreakdown = priceBreakdown;
        this.selectedDates.nights = priceBreakdown.nights;
        this.selectedDates.totalDays = priceBreakdown.nights;
        this.selectedDates.estimatedTotal = priceBreakdown.total;
        // Actualizar descuentos aplicables
        this.selectedDates.applicableDiscounts = [];
        if (priceBreakdown.weeklyDiscount) {
          this.selectedDates.applicableDiscounts.push(`Descuento semanal: ${priceBreakdown.weeklyDiscount.percentage}%`);
        }
        if (priceBreakdown.monthlyDiscount) {
          this.selectedDates.applicableDiscounts.push(`Descuento mensual: ${priceBreakdown.monthlyDiscount.percentage}%`);
        }
        console.log('Price calculation completed successfully');
      },
      error: error => {
        console.error('Price calculation error:', error);
        // Fallback: cálculo básico manual
        this.calculateBasicPrice();
      }
    });
  }
  calculateBasicPrice() {
    if (!this.property || !this.selectedDates.checkIn || !this.selectedDates.checkOut) return;
    const nights = this.calculateNights(this.selectedDates.checkIn, this.selectedDates.checkOut);
    const subtotal = this.property.pricePerNight * nights;
    const iva = subtotal * 0.19; // 19% IVA Colombia
    const total = subtotal + iva;
    this.priceBreakdown = {
      pricePerNight: this.property.pricePerNight,
      nights,
      subtotal,
      iva: {
        percentage: 19,
        amount: iva
      },
      total,
      totalCOP: total
    };
    this.selectedDates.nights = nights;
    this.selectedDates.totalDays = nights;
    this.selectedDates.estimatedTotal = total;
    console.log('Basic price calculated:', this.priceBreakdown);
  }
  // ================================
  // 📋 ACTUALIZACIÓN DE BOOKING
  // ================================
  updateBookingDates(checkIn, checkOut) {
    this.bookingService.updateCurrentBooking({
      checkInDate: checkIn,
      checkOutDate: checkOut,
      nights: this.calculateNights(checkIn, checkOut)
    }).subscribe();
  }
  updateBookingGuests(guests) {
    if (!this.property || guests.total > this.property.maxGuests) {
      console.warn(`Máximo ${this.property?.maxGuests} huéspedes permitidos`);
      return;
    }
    this.bookingService.updateCurrentBooking({
      guests
    }).subscribe();
  }
  updateBookingDetails(details) {
    const guestInfo = {
      firstName: details.firstName,
      lastName: details.lastName,
      email: details.email,
      phone: details.phone,
      whatsapp: details.whatsapp || details.phone,
      documentType: details.documentType,
      documentNumber: details.documentNumber,
      nationality: details.nationality,
      emergencyContact: details.emergencyContactName ? {
        name: details.emergencyContactName,
        phone: details.emergencyContactPhone,
        relationship: details.emergencyContactRelationship
      } : undefined
    };
    this.bookingService.updateCurrentBooking({
      guestInfo,
      specialRequests: details.specialRequests,
      estimatedArrivalTime: details.estimatedArrivalTime,
      purposeOfStay: details.purposeOfStay,
      isFirstTimeInArmenia: details.isFirstTimeInArmenia
    }).subscribe();
  }
  updateFormsFromBooking(booking) {
    // Actualizar formulario de fechas
    if (booking.checkInDate && booking.checkOutDate) {
      this.datesForm.patchValue({
        checkInDate: booking.checkInDate,
        checkOutDate: booking.checkOutDate
      }, {
        emitEvent: false
      });
      this.selectedDates.checkIn = booking.checkInDate;
      this.selectedDates.checkOut = booking.checkOutDate;
    }
    // Actualizar formulario de huéspedes
    if (booking.guests) {
      this.guestsForm.patchValue({
        adults: booking.guests.adults,
        children: booking.guests.children,
        infants: booking.guests.infants
      }, {
        emitEvent: false
      });
    }
    // Actualizar formulario de detalles
    if (booking.guestInfo) {
      this.detailsForm.patchValue({
        firstName: booking.guestInfo.firstName,
        lastName: booking.guestInfo.lastName,
        email: booking.guestInfo.email,
        phone: booking.guestInfo.phone,
        whatsapp: booking.guestInfo.whatsapp,
        documentType: booking.guestInfo.documentType,
        documentNumber: booking.guestInfo.documentNumber,
        nationality: booking.guestInfo.nationality,
        emergencyContactName: booking.guestInfo.emergencyContact?.name,
        emergencyContactPhone: booking.guestInfo.emergencyContact?.phone,
        emergencyContactRelationship: booking.guestInfo.emergencyContact?.relationship
      }, {
        emitEvent: false
      });
    }
  }
  // ================================
  // 🚀 NAVEGACIÓN ENTRE PASOS
  // ================================
  nextStep() {
    if (!this.canProceed) {
      console.warn('Cannot proceed to next step');
      return;
    }
    if (this.currentStep < this.totalSteps) {
      this.currentStep++;
      this.scrollToTop();
      console.log('Moved to step:', this.currentStep);
    }
  }
  previousStep() {
    if (this.currentStep > 1) {
      this.currentStep--;
      this.scrollToTop();
      console.log('Moved to step:', this.currentStep);
    }
  }
  goToStep(step) {
    if (step >= 1 && step <= this.totalSteps) {
      this.currentStep = step;
