    this.bookingService.submitBooking().pipe(takeUntil(this.destroy$), catchError(error => {
      this.error = 'Error al crear la reserva: ' + error.message;
      this.isSubmitting = false;
      return of(null);
    })).subscribe(booking => {
      this.isSubmitting = false;
