    return (this.dateValidation?.isValid || false) && this.datesForm?.valid && this.guestsForm?.valid && this.detailsForm?.valid;
  }
  get stepErrors() {
    if (!this.bookingProgress) return [];
    const currentStepIndex = this.currentStep - 1;
    return this.bookingProgress.steps[currentStepIndex]?.errors || [];
  }
  get totalPrice() {
    return this.priceBreakdown?.total || 0;
  }
  get hasDiscounts() {
    return !!(this.priceBreakdown?.weeklyDiscount || this.priceBreakdown?.monthlyDiscount);
  }
